prompt --application/shared_components/security/authorizations/平台导航可访问
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(48352986620823003)
,p_name=>unistr('\5E73\53F0\5BFC\822A\53EF\8BBF\95EE')
,p_static_id=>unistr('\5E73\53F0\5BFC\822A\53EF\8BBF\95EE')
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    'begin',
    '    if kbot_apex_auth.is_platform_admin(:APP_USER) then',
    '        return true;',
    '    end if;',
    '    for r in (',
    '        select 1',
    '          from kbot_platform_user_role ur',
    '          join kbot_platform_user u',
    '            on u.user_id = ur.user_id',
    '           and u.status = ''ACTIVE''',
    '          join kbot_app_role ar',
    '            on ar.app_id = ''platform''',
    '           and ar.role_code = ur.role_code',
    '           and ar.status = ''ACTIVE''',
    '          join kbot_app_role_permission rp',
    '            on rp.app_id = ar.app_id',
    '           and rp.role_code = ar.role_code',
    '         where ur.user_id = :APP_USER',
    '           and ur.status = ''ACTIVE''',
    '           and rp.permission_code in (',
    '                   ''platform:app_manage'',',
    '                   ''platform:user_manage'',',
    '                   ''platform:role_manage'',',
    '                   ''platform:app_grant_manage'',',
    '                   ''platform:domain_manage''',
    '               )',
    '           and rownum = 1',
    '    ) loop',
    '        return true;',
    '    end loop;',
    '    return false;',
    'end;')))).to_clob
,p_error_message=>unistr('\6743\9650\4E0D\8DB3\3002')
,p_caching=>'BY_USER_BY_PAGE_VIEW'
);
end;
