,p_item_sequence=>27
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select listagg(permission_code, ''|'')',
'           within group (order by permission_code)',
'  from (',
'        select distinct rp.permission_code',
'          from kbot_app_member_role mr',
'          join kbot_app_member m',
'            on m.app_id = mr.app_id',
'           and m.user_id = mr.user_id',
'           and m.status = ''ACTIVE''',
'          join kbot_platform_app a',
'            on a.app_id = mr.app_id',
'           and a.status = ''ACTIVE''',
'          join kbot_app_domain ad',
'            on ad.app_id = mr.app_id',
'           and ad.domain_id = :P0_DOMAIN_ID',
'           and ad.status = ''ACTIVE''',
'          join kbot_platform_user u',
'            on u.user_id = mr.user_id',
'           and u.status = ''ACTIVE''',
'          join kbot_app_role r',
'            on r.app_id = mr.app_id',
'           and r.role_code = mr.role_code',
'           and r.status = ''ACTIVE''',
'          join kbot_app_role_permission rp',
'            on rp.app_id = r.app_id',
'           and rp.role_code = r.role_code',
'         where mr.user_id = :APP_USER',
'           and mr.status = ''ACTIVE''',
'           and (',
'               mr.scope_mode = ''ALL_APP_DOMAINS''',
'               or exists (',
'                   select 1',
'                     from kbot_app_member_role_scope s',
'                    where s.app_id = mr.app_id',
'                      and s.user_id = mr.user_id',
'                      and s.role_code = mr.role_code',
'                      and s.domain_id = :P0_DOMAIN_ID',
'               )',
'           )',
'       )'))
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_HIDDEN'
,p_protection_level=>'I'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(48367955089825139)
,p_name=>'P0_PERMISSION_CODES'
,p_item_sequence=>26
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select listagg(permission_code, ''|'')',
'           within group (order by permission_code)',
'  from (',
'        select p.permission_code',
'          from kbot_permission p',
'         where (',
'                   v(''P0_AUTH_ENTRY_KIND'') = ''PLATFORM''',
'                   or :APP_PAGE_ID in (10, 80, 90)',
'               )',
'           and kbot_apex_auth.is_platform_admin(:APP_USER)',
'        union',
'        select distinct rp.permission_code',
'          from kbot_platform_user_role ur',
'          join kbot_platform_user u on u.user_id = ur.user_id and u.status = ''ACTIVE''',
'          join kbot_app_role r on r.app_id = ''platform'' and r.role_code = ur.role_code and r.status = ''ACTIVE''',
'          join kbot_app_role_permission rp on rp.app_id = r.app_id and rp.role_code = r.role_code',
'         where (',
'                   v(''P0_AUTH_ENTRY_KIND'') = ''PLATFORM''',
'                   or :APP_PAGE_ID in (10, 80, 90)',
'               )',
'           and ur.user_id = :APP_USER and ur.status = ''ACTIVE''',
'        union',
'        select distinct rp.permission_code',
'          from kbot_app_member_role mr',
'          join kbot_app_member m on m.app_id = mr.app_id and m.user_id = mr.user_id and m.status = ''ACTIVE''',
'          join kbot_platform_app a on a.app_id = mr.app_id and a.status = ''ACTIVE''',
'          join kbot_app_domain ad on ad.app_id = mr.app_id and ad.domain_id = :P0_DOMAIN_ID and ad.status = ''ACTIVE''',
'          join kbot_platform_user u on u.user_id = mr.user_id and u.status = ''ACTIVE''',
'          join kbot_app_role r on r.app_id = mr.app_id and r.role_code = mr.role_code and r.status = ''ACTIVE''',
'          join kbot_app_role_permission rp on rp.app_id = r.app_id and rp.role_code = r.role_code',
'         where (',
'               v(''P0_AUTH_ENTRY_KIND'') = ''PLATFORM''',
'               or :APP_PAGE_ID in (10, 80, 90)',
'               or (',
'                   v(''P0_AUTH_ENTRY_KIND'') = ''BUSINESS''',
'                   and mr.app_id = v(''P0_AUTH_APP_ID'')',
'               )',
'           )',
'           and mr.user_id = :APP_USER and mr.status = ''ACTIVE''',
'           and (mr.scope_mode = ''ALL_APP_DOMAINS'' or exists (',
'               select 1 from kbot_app_member_role_scope s',
'                where s.app_id = mr.app_id and s.user_id = mr.user_id',
'                  and s.role_code = mr.role_code and s.domain_id = :P0_DOMAIN_ID',
'           ))',
'       )'))
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_HIDDEN'
,p_protection_level=>'I'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(48366686849825137)
,p_name=>'P0_SERVICE_URL'
,p_item_sequence=>10
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select max(',
'           case',
