begin
wwv_flow_imp_page.create_page(
 p_id=>1
,p_name=>unistr('\5E94\7528\4E3B\9875')
,p_alias=>'HOME'
,p_step_title=>unistr('\5E73\53F0\7BA1\7406-\5E94\7528\4E3B\9875')
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_html_page_header=>'<script src="#APP_FILES#js/kbot-theme-init.js?v=20260812_2"></script>'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.__kbotAgentWindows = window.__kbotAgentWindows || Object.create(null);',
'',
'window.kbotOpenAgentApp = function (link) {',
'    const targetName = String(link?.getAttribute("target") || "");',
'    const targetUrl = String(link?.href || "");',
'    const appId = String(link?.dataset?.kbotAppId || "");',
'',
'    if (!targetName || !targetUrl || !appId || targetName === "_blank") {',
'        return true;',
'    }',
'',
'    const presenceKey = `kbot:agent-window:${appId}`;',
'    const focusKey = `${presenceKey}:focus`;',
'    const focusAckKey = `${focusKey}:ack`;',
'    const openedWindow = window.__kbotAgentWindows[appId];',
'    let presence = null;',
'',
'    const openTarget = function (reservedWindow) {',
'        localStorage.removeItem(presenceKey);',
'        const newWindow = reservedWindow && !reservedWindow.closed',
'            ? reservedWindow',
'            : window.open(targetUrl, targetName);',
'        if (newWindow) {',
'            if (reservedWindow) {',
'                newWindow.name = targetName;',
'                newWindow.location.replace(targetUrl);',
'            }',
'            window.__kbotAgentWindows[appId] = newWindow;',
'            newWindow.focus();',
'            return false;',
'        }',
'        return true;',
'    };',
'',
'    if (openedWindow && !openedWindow.closed) {',
'        openedWindow.focus();',
'        return false;',
'    }',
'',
'    try {',
'        presence = JSON.parse(localStorage.getItem(presenceKey) || "null");',
'    } catch (error) {',
'        localStorage.removeItem(presenceKey);',
'    }',
'',
'    if (!presence?.tabId) {',
'        return openTarget();',
'    }',
'',
'    const reservedWindow = window.open("about:blank", "_blank");',
'    if (!reservedWindow) {',
'        return false;',
'    }',
'',
'    const requestId = `${Date.now()}-${Math.random().toString(36).slice(2)}`;',
'    let focusAcknowledged = false;',
'    let fallbackTimer = null;',
'',
'    const readAcknowledgement = function (rawValue) {',
'        try {',
'            const acknowledgement = JSON.parse(rawValue || "null");',
'            return acknowledgement?.requestId === requestId;',
'        } catch (error) {',
'            return false;',
'        }',
'    };',
'',
'    const stopWaiting = function () {',
'        window.removeEventListener("storage", handleAcknowledgement);',
'        if (fallbackTimer) {',
'            window.clearTimeout(fallbackTimer);',
'        }',
'    };',
'',
'    const handleAcknowledgement = function (event) {',
'        if (event.key === focusAckKey && readAcknowledgement(event.newValue)) {',
'            focusAcknowledged = true;',
'            stopWaiting();',
'            reservedWindow.close();',
'        }',
'    };',
'',
'    window.addEventListener("storage", handleAcknowledgement);',
'    localStorage.setItem(focusKey, JSON.stringify({',
'        requestId,',
'        requestedAt: Date.now()',
'    }));',
'',
'    fallbackTimer = window.setTimeout(function () {',
'        if (!focusAcknowledged && readAcknowledgement(localStorage.getItem(focusAckKey))) {',
'            focusAcknowledged = true;',
'        }',
'        stopWaiting();',
'        if (focusAcknowledged) {',
'            reservedWindow.close();',
'        } else {',
'            openTarget(reservedWindow);',
'        }',
'    }, 1500);',
'',
'    return false;',
'};'))
,p_inline_css=>'.kbot-launcher{max-width:1180px;margin:0 auto;padding:32px 16px 48px;color:#1d2925}.kbot-launcher ::selection{background:#cce7df;color:#123d33}.kbot-launcher__intro{padding:24px 8px 28px;border-bottom:1px solid #d9e2de}.kbot-launcher__intro .kbot-lau'
||'ncher__context{margin:0 0 12px;color:#285f50;font-size: 14px!important;font-weight:600;line-height:1.4}.kbot-launcher__intro h1{max-width:760px;margin:0;color:#1d2925;font-size:24px;font-weight:700;line-height:1.3;letter-spacing:-.02em;text-wrap:bala'
||'nce}.kbot-launcher__intro p{max-width:75ch;margin:12px 0 0;color:#68756f;font-size:12px;line-height:1.75}.kbot-launcher__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:24px}.kbot-launcher__card{display:grid;grid-t'
||'emplate-columns:56px minmax(0,1fr);gap:16px;align-items:start;min-height:164px;padding:20px;border:1px solid #d9e2de;border-radius:14px;background:#fff;color:#173a31;text-decoration:none;box-shadow:0 10px 26px rgba(20,53,47,.07);transition:transform '
||'.18s ease-out,border-color .18s ease-out,box-shadow .18s ease-out}.kbot-launcher__card:hover{transform:translateY(-2px);border-color:#6b9f91;box-shadow:0 16px 32px rgba(20,53,47,.11)}.kbot-launcher__card:focus-visible{outline:3px solid rgba(18,107,89'
||',.28);outline-offset:3px}.kbot-launcher__icon{display:block;width:56px;height:56px;border-radius:14px;object-fit:cover}.kbot-launcher__icon--fallback{display:grid;place-items:center;background:#e5f3ef;color:#0c6b58;font-size:24px}.kbot-launcher__body'
||'{display:flex;min-width:0;min-height:124px;flex-direction:column}.kbot-launcher__card h2{margin:2px 0 8px;color:#173a31;font-size:14px;font-weight:700;line-height:1.45}.kbot-launcher__description{margin:0;color:#5f6f69;font-size:12px;line-height:1.65'
||'}.kbot-launcher__meta{margin-top:auto;padding-top:14px;color:#71817b;font-size:12px;line-height:1.4}.kbot-launcher__empty{grid-column:1/-1;padding:24px;border:1px dashed #9db6af;border-radius:14px;background:#f7faf9;color:#526b65;font-size:12px;line-'
||'height:1.6}@media(max-width:900px){.kbot-launcher__grid{grid-template-columns:1fr}.kbot-launcher__card{min-height:auto}.kbot-launcher__body{min-height:112px}}@media(max-width:640px){.kbot-launcher{padding:20px 12px 32px}.kbot-launcher__intro{padding:'
||'16px 4px 22px}.kbot-launcher__grid{margin-top:20px}.kbot-launcher__card{grid-template-columns:48px minmax(0,1fr);gap:14px;padding:16px}.kbot-launcher__icon{width:48px;height:48px}.kbot-launcher__body{min-height:108px}}@media(prefers-reduced-motion:re'
||'duce){.kbot-launcher__card{transition:none}.kbot-launcher__card:hover{transform:none}}'
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_page_is_public_y_n=>'Y'
