wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(48368720889825140)
,p_plug_name=>unistr('KBOT\5E94\7528')
,p_static_id=>'app-launcher'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
unistr('    l_html clob := ''<main class="kbot-launcher"><section class="kbot-launcher__intro"><p class="kbot-launcher__context">\5E73\53F0\5DE5\4F5C\53F0</p><h1>\6B22\8FCE\4F7F\7528 KBot \667A\80FD\4F53\5E73\53F0</h1><p>KBot \5C06\4F01\4E1A\77E5\8BC6\3001\6570\636E\4E0E\8FD0\7EF4\80FD\529B\7EC4\7EC7\4E3A\5404\53F8\5176\804C\7684\667A\80FD\4F53\5E94\7528\FF0C\5E76\7531\7EDF\4E00\5E73\53F0\7BA1\7406\8D26\53F7\3001\6743\9650\3001\8FDE\63A5\3001\4E1A\52A1\57DF\548C\6A21\578B\914D\7F6E\3002\9009\62E9\4E0B\65B9\5E94\7528\FF0C\8FDB\5165\5BF9\5E94\5DE5\4F5C\53F0\5B8C\6210\4E13\4E1A\4EFB\52A1\3002</p></section><')
||unistr('section class="kbot-launcher__grid" aria-label="KBot \667A\80FD\4F53\5E94\7528">'';'),
'    l_count pls_integer := 0;',
'    l_description varchar2(4000);',
'    l_icon_src clob;',
'    l_target varchar2(255);',
'    l_launch_attributes varchar2(1000);',
'begin',
'    for r in (',
'        select a.application_id,',
'               a.application_name,',
'               a.alias,',
'               dbms_lob.substr(a.application_comment, 1000, 1) as application_description,',
'               f.mime_type as icon_mime_type,',
'               f.file_content as icon_content,',
'               nvl(s.value, ''N'') as reuse_launch',
'          from apex_applications a',
'          left join apex_application_static_files f',
'            on f.application_id = a.application_id',
'           and f.file_name = ''icons/app-icon-144-rounded.png''',
'          left join apex_application_settings s',
'            on s.application_id = a.application_id',
'           and s.static_id = ''KBOT_LAUNCH_REUSE''',
'         where a.workspace_id = :WORKSPACE_ID',
'           and a.application_group = ''KBOT Agent Apps''',
'           and nvl(a.availability_status, ''Available'') like ''Available%''',
'         order by a.application_id',
'    ) loop',
'        l_count := l_count + 1;',
'        l_description := coalesce(',
'            trim(r.application_description),',
unistr('            ''\8FDB\5165\8BE5\667A\80FD\4F53\5E94\7528\FF0C\6309\8D26\53F7\6743\9650\4F7F\7528\5BF9\5E94\529F\80FD\4E0E\6570\636E\3002'''),
'        );',
'        if r.icon_content is not null then',
'            l_icon_src := ''data:'' || nvl(r.icon_mime_type, ''image/png'') || '';base64,'' ||',
'                apex_web_service.blob2clobbase64(r.icon_content);',
'        else',
'            l_icon_src := null;',
'        end if;',
'        if upper(r.reuse_launch) = ''Y'' then',
'            l_target := ''kbot-agent-'' || to_char(r.application_id);',
'            l_launch_attributes := '' target="'' || apex_escape.html_attribute(l_target) ||',
'                ''" data-kbot-app-id="'' || to_char(r.application_id) ||',
'                ''" onclick="return kbotOpenAgentApp(this);"'';',
'        else',
'            l_launch_attributes := '' target="_blank" rel="noopener noreferrer"'';',
'        end if;',
'        l_html := l_html || ''<a class="kbot-launcher__card" href="'' ||',
'            apex_escape.html_attribute(apex_page.get_url(p_application => r.application_id, p_page => 10, p_session => 0)) ||',
'            ''"'' || l_launch_attributes || ''>'';',
'        if l_icon_src is not null then',
'            l_html := l_html || ''<img class="kbot-launcher__icon" src="'' ||',
'                apex_escape.html_attribute(l_icon_src) || ''" alt="">'';',
'        else',
'            l_html := l_html || ''<span class="kbot-launcher__icon kbot-launcher__icon--fallback fa fa-cube" aria-hidden="true"></span>'';',
'        end if;',
'        l_html := l_html || ''<span class="kbot-launcher__body"><h2>'' ||',
'            apex_escape.html(r.application_name) || ''</h2><span class="kbot-launcher__description">'' ||',
'            apex_escape.html(l_description) || ''</span><span class="kbot-launcher__meta">APP '' ||',
unistr('            to_char(r.application_id) || '' \00B7 \767B\5F55\540E\8FDB\5165</span></span></a>'';'),
'    end loop;',
'    if l_count = 0 then',
unistr('        l_html := l_html || ''<div class="kbot-launcher__empty">\5F53\524D\6CA1\6709\53EF\7528\7684 KBot \667A\80FD\4F53\5E94\7528\3002\8BF7\8054\7CFB\5E73\53F0\7BA1\7406\5458\68C0\67E5\5E94\7528\7EC4\4E0E\53D1\5E03\72B6\6001\3002</div>'';'),
'    end if;',
'    return l_html || ''</section></main>'';',
'end;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
end;
