'select display_name,',
'       served_model_name,',
'       case category',
unistr('           when 1 then ''\5927\8BED\8A00\6A21\578B'''),
unistr('           when 2 then ''\6587\672C\5411\91CF'''),
unistr('           when 3 then ''\56FE\7247\5411\91CF'''),
unistr('           when 5 then ''\89C6\89C9\6A21\578B'''),
'       end as category,',
'       provider,',
'       provider_model_name,',
'       api_endpoint,',
unistr('       case when api_key is null then ''\672A\914D\7F6E'' else ''\5DF2\914D\7F6E'' end as api_key_status,'),
'       case status',
unistr('           when 0 then ''\7981\7528'''),
unistr('           when 1 then ''\542F\7528'''),
unistr('           when 2 then ''\5F52\6863'''),
'       end as status,',
'       descs,',
'       updated_at,',
'       null as edit_action',
'  from kbot_ai_model',
' where category in (1, 2, 3, 5)',
' order by updated_at desc nulls last,',
'          display_name'))
