,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select domain_id,',
'       name,',
'       status as status_code,',
'       case status',
unistr('           when ''ACTIVE'' then ''\542F\7528'''),
unistr('           when ''DISABLED'' then ''\505C\7528'''),
'           else status',
'       end as status,',
'       coalesce(',
'           (',
unistr('               select listagg(a.display_name, ''\3001'') within group (order by a.display_name)'),
'                 from kbot_app_domain ad',
'                 join kbot_platform_app a',
'                   on a.app_id = ad.app_id',
'                where ad.domain_id = d.domain_id',
'                  and ad.status = ''ACTIVE''',
'                  and a.status = ''ACTIVE''',
'                  and a.member_assignable = ''Y''',
'           ),',
unistr('           ''\672A\7ED1\5B9A'''),
'       ) as bound_apps,',
'       description,',
'       to_char(updated_at, ''YYYY-MM-DD HH24:MI'') as updated_at,',
'       null as edit_action',
'  from kbot_platform_domain d',
' order by name'))
