wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48388328528825262)
,p_process_sequence=>4
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('\751F\6210\6A21\578B ID')
,p_static_id=>'p63-generate-model-id'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_elapsed interval day(9) to second(6);',
'    v_epoch_ms number;',
'    v_random_hex varchar2(20);',
'    v_variant_hex varchar2(1);',
'begin',
'    v_elapsed := sys_extract_utc(systimestamp)',
'        - timestamp ''1970-01-01 00:00:00'';',
'    v_epoch_ms :=',
'        extract(day from v_elapsed) * 86400000',
'        + extract(hour from v_elapsed) * 3600000',
'        + extract(minute from v_elapsed) * 60000',
'        + floor(extract(second from v_elapsed) * 1000);',
'    v_random_hex := lower(rawtohex(dbms_crypto.randombytes(10)));',
'    v_variant_hex := substr(',
'        ''89ab'',',
'        mod(to_number(substr(v_random_hex, 4, 1), ''x''), 4) + 1,',
'        1',
'    );',
'    :P63_MODEL_ID := lower(',
'        lpad(to_char(v_epoch_ms, ''fmxxxxxxxxxxxx''), 12, ''0'')',
'        || ''7''',
'        || substr(v_random_hex, 1, 3)',
'        || v_variant_hex',
'        || substr(v_random_hex, 5, 15)',
'    );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>48388328528825262
);
