wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48388519816825312)
,p_process_sequence=>15
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('\4FDD\5B58\6A21\578B\53C2\6570\548C\5BC6\94A5')
,p_static_id=>'p63-store-model-params-and-api-key'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_category    number := to_number(:P63_CATEGORY);',
'    l_provider    varchar2(64) := :P63_PROVIDER;',
'    l_params      json_object_t := json_object_t();',
'    l_oci_config  json_object_t;',
'    l_json        clob;',
'    l_has_api_key number;',
'begin',
'    if l_category = 1 and l_provider not in (''api_deepseek'', ''api_qwen'', ''chatgpt'', ''oci'') then',
unistr('        raise_application_error(-20001, ''\5F53\524D\5927\8BED\8A00\6A21\578B\670D\52A1\5546\4E0D\53D7\652F\6301\3002'');'),
'    elsif l_category = 2 and l_provider not in (''local_qwen'', ''local_bge'', ''api_qwen'', ''chatgpt'', ''oci'') then',
unistr('        raise_application_error(-20001, ''\5F53\524D\6587\672C\5411\91CF\670D\52A1\5546\4E0D\53D7\652F\6301\3002'');'),
'    elsif l_category = 3 and l_provider <> ''local_qwen'' then',
unistr('        raise_application_error(-20001, ''\56FE\7247\5411\91CF\5F53\524D\53EA\652F\6301 local_qwen\3002'');'),
'    elsif l_category = 5 and l_provider not in (''api_qwen'', ''chatgpt'') then',
unistr('        raise_application_error(-20001, ''\5F53\524D\89C6\89C9\6A21\578B\670D\52A1\5546\4E0D\53D7\652F\6301\3002'');'),
'    elsif l_category not in (1, 2, 3, 5) then',
unistr('        raise_application_error(-20001, ''\5F53\524D\6A21\578B\7C7B\522B\4E0D\53D7\652F\6301\3002'');'),
'    end if;',
'',
'    select case when api_key is not null then 1 else 0 end',
'      into l_has_api_key',
'      from kbot_ai_model',
'     where served_model_name = :P63_SERVED_MODEL_NAME;',
'',
'    if l_provider in (''api_deepseek'', ''api_qwen'', ''chatgpt'') and :P63_CLEAR_API_KEY = ''Y'' then',
unistr('        raise_application_error(-20001, ''API \670D\52A1\5546\4E0D\80FD\5728\4FDD\5B58\65F6\6E05\9664API \5BC6\94A5\3002'');'),
'    end if;',
'',
'    if l_provider in (''api_deepseek'', ''api_qwen'', ''chatgpt'') and :P63_API_KEY is null and l_has_api_key = 0 then',
unistr('        raise_application_error(-20001, ''\5F53\524D\670D\52A1\5546\5FC5\987B\914D\7F6E API \5BC6\94A5\3002'');'),
'    end if;',
'',
'    if (l_category in (1, 5) or l_provider = ''oci'') and :P63_API_ENDPOINT is null then',
unistr('        raise_application_error(-20001, ''\5F53\524D\6A21\578B\5FC5\987B\914D\7F6E API \7AEF\70B9\3002'');'),
'    end if;',
'',
'    if l_category = 2 and (:P63_EMBEDDING_DIMENSION is null or to_number(:P63_EMBEDDING_DIMENSION) <= 0) then',
unistr('        raise_application_error(-20001, ''\6587\672C\5411\91CF\7EF4\5EA6\5FC5\987B\662F\6B63\6574\6570\3002'');'),
'    end if;',
'    if l_category = 2 then',
'        l_params.put(''embedding_dimension'', to_number(:P63_EMBEDDING_DIMENSION));',
'    end if;',
'',
'    if l_provider in (''local_qwen'', ''local_bge'') and l_category in (2, 3) and :P63_MODEL_PATH is null then',
unistr('        raise_application_error(-20001, ''\672C\5730\6A21\578B\5FC5\987B\914D\7F6E\6A21\578B\8DEF\5F84\3002'');'),
'    end if;',
'',
'    if l_provider = ''oci'' and (:P63_OCI_USER is null or :P63_OCI_FINGERPRINT is null or :P63_OCI_TENANCY is null or :P63_OCI_COMPARTMENT_ID is null or :P63_OCI_REGION is null or (:P63_OCI_KEY_FILE is null and :P63_OCI_PRIVATE_KEY is null)) then',
unistr('        raise_application_error(-20001, ''OCI \670D\52A1\5546\5FC5\987B\5B8C\6574\914D\7F6E\7528\6237\3001\6307\7EB9\3001\79DF\6237\3001\533A\95F4\3001\533A\57DF\FF0C\5E76\5728 \79C1\94A5\6587\4EF6 \4E0E OCI \79C1\6709\5BC6\94A5\4E2D\81F3\5C11\586B\5199\4E00\9879\3002'');'),
'    end if;',
'    if l_provider = ''oci'' then',
'        l_oci_config := json_object_t();',
'        l_oci_config.put(''user'', :P63_OCI_USER);',
'        l_oci_config.put(''fingerprint'', :P63_OCI_FINGERPRINT);',
'        l_oci_config.put(''tenancy'', :P63_OCI_TENANCY);',
'        l_oci_config.put(''region'', :P63_OCI_REGION);',
'        if :P63_OCI_KEY_FILE is not null then',
'            l_oci_config.put(''key_file'', :P63_OCI_KEY_FILE);',
'        end if;',
'        if :P63_OCI_PRIVATE_KEY is not null then',
'            l_oci_config.put(''key_content'', :P63_OCI_PRIVATE_KEY);',
'        end if;',
'        l_params.put(''config_file'', l_oci_config);',
'    end if;',
'    if l_provider = ''oci'' and :P63_OCI_PASSPHRASE is not null then',
'        l_oci_config.put(''pass_phrase'', :P63_OCI_PASSPHRASE);',
'        l_params.put(''config_file'', l_oci_config);',
'    end if;',
'',
'    if l_category in (1, 5) and :P63_TEMPERATURE is not null then',
'        l_params.put(''temperature'', to_number(:P63_TEMPERATURE));',
'    end if;',
'    if l_category in (1, 2, 5) and :P63_MAX_TOKENS is not null then',
'        l_params.put(''max_tokens'', to_number(:P63_MAX_TOKENS));',
'    end if;',
'    if l_category = 1 and :P63_TOP_P is not null then',
'        l_params.put(''top_p'', to_number(:P63_TOP_P));',
'    end if;',
'    if l_category = 1 and :P63_FREQUENCY_PENALTY is not null then',
'        l_params.put(''frequency_penalty'', to_number(:P63_FREQUENCY_PENALTY));',
'    end if;',
'    if l_category = 1 and :P63_PRESENCE_PENALTY is not null then',
'        l_params.put(''presence_penalty'', to_number(:P63_PRESENCE_PENALTY));',
'    end if;',
'    if l_category in (1, 2, 3, 5) and :P63_TIMEOUT is not null then',
'        l_params.put(''timeout'', to_number(:P63_TIMEOUT));',
'    end if;',
'    if l_category in (3, 5) and :P63_MAX_RETRIES is not null then',
'        l_params.put(''max_retries'', to_number(:P63_MAX_RETRIES));',
'    end if;',
'    if l_category = 2 and :P63_BATCH_SIZE is not null then',
'        l_params.put(''batch_size'', to_number(:P63_BATCH_SIZE));',
'    end if;',
'    if l_category = 2 then',
'        l_params.put(''normalize'', :P63_NORMALIZE = ''Y'');',
'    end if;',
'    if l_category in (2, 3) and l_provider in (''local_qwen'', ''local_bge'') then',
'        l_params.put(''model_path'', :P63_MODEL_PATH);',
'    end if;',
'    if l_category in (2, 3) and l_provider in (''local_qwen'', ''local_bge'') and :P63_DEVICE is not null then',
'        l_params.put(''device'', :P63_DEVICE);',
'    end if;',
'    if l_provider = ''oci'' then',
'        l_params.put(''compartment_id'', :P63_OCI_COMPARTMENT_ID);',
'    end if;',
'    if l_category = 3 and :P63_DIMENSION is not null then',
'        l_params.put(''dimension'', to_number(:P63_DIMENSION));',
'    end if;',
'    l_json := l_params.to_clob();',
'',
'    update kbot_ai_model',
'       set model_params = json_query(l_json, ''$'' returning json),',
'           api_key = decode(:P63_CLEAR_API_KEY, ''Y'', to_clob(null), nvl(:P63_API_KEY, api_key)),',
'           updated_by = :APP_USER,',
'           updated_at = current_timestamp',
'     where served_model_name = :P63_SERVED_MODEL_NAME;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,APPLY-CHANGES'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>48388519816825312
);
end;
