wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48390426574825313)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('\68C0\67E5\4E1A\52A1\57DF\5220\9664\4F9D\8D56')
,p_static_id=>'p64-guard-delete'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_row_count     pls_integer;',
'    l_blocker_count pls_integer := 0;',
'    l_protected_count pls_integer;',
'    l_blockers      varchar2(2000);',
'    l_table_name    varchar2(261);',
'    l_domain_id     number := to_number(:P64_DOMAIN_ID);',
'begin',
'    if l_domain_id is null then',
unistr('        raise_application_error(-20001, ''\672A\627E\5230\9700\8981\5220\9664\7684\4E1A\52A1\57DF\3002'');'),
'    end if;',
'',
'    select count(*)',
'      into l_protected_count',
'      from kbot_app_domain ad',
'     where ad.domain_id = l_domain_id',
'       and ad.app_id in (''aiops'', ''km_asset'')',
'       and ad.status = ''ACTIVE'';',
'',
'    if l_protected_count > 0 then',
'        raise_application_error(',
'            -20001,',
unistr('            ''AIOps \4E0E\77E5\8BC6\8D44\4EA7\4E1A\52A1\57DF\7531\670D\52A1\811A\672C\7EF4\62A4\FF0C\4E0D\80FD\5728\6B64\5220\9664\3002'''),
'        );',
'    end if;',
'',
'    for r in (',
'        select t.table_name',
'          from user_tables t',
'          join user_tab_columns c',
'            on c.table_name = t.table_name',
'         where c.column_name = ''DOMAIN_ID''',
'           and t.table_name not in (''KBOT_PLATFORM_DOMAIN'', ''KBOT_APP_DOMAIN'')',
'         order by t.table_name',
'    ) loop',
'        l_table_name := dbms_assert.sql_object_name(r.table_name);',
'        execute immediate',
'            ''select count(*) from '' || l_table_name ||',
'            '' where domain_id = :domain_id and rownum = 1''',
'            into l_row_count',
'            using l_domain_id;',
'',
'        if l_row_count > 0 then',
'            l_blocker_count := l_blocker_count + 1;',
'            if l_blocker_count <= 5 then',
'                l_blockers := l_blockers ||',
unistr('                    case when l_blockers is null then null else ''\3001'' end ||'),
'                    r.table_name;',
'            end if;',
'        end if;',
'    end loop;',
'',
'    if l_blocker_count > 0 then',
'        raise_application_error(',
'            -20001,',
unistr('            ''\8BE5\4E1A\52A1\57DF\5DF2\4EA7\751F\4E1A\52A1\6570\636E\FF0C\4E0D\80FD\7269\7406\5220\9664\3002\5173\8054\8868\FF1A'' ||'),
'            l_blockers ||',
unistr('            case when l_blocker_count > 5 then '' \7B49'' else null end ||'),
unistr('            ''\FF1B\8BF7\5C06\72B6\6001\6539\4E3A\201C\505C\7528\201D\3002'''),
'        );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'DELETE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>48390426574825313
);
