 p_id=>wwv_flow_imp.id(48390317208825313)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('\8BFB\53D6\9002\7528\5E94\7528')
,p_static_id=>'p64-load-app-bindings'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_binding_count pls_integer;',
'begin',
'    if :P64_DOMAIN_ID is not null then',
'        select min(ad.app_id), count(*)',
'          into :P64_APP_ID, l_binding_count',
'          from kbot_app_domain ad',
'          join kbot_platform_app a',
'            on a.app_id = ad.app_id',
'         where ad.domain_id = to_number(:P64_DOMAIN_ID)',
'           and ad.status = ''ACTIVE''',
'           and a.status = ''ACTIVE''',
'           and a.member_assignable = ''Y'';',
'',
'        if l_binding_count > 1 then',
unistr('            raise_application_error(-20001, ''\5F53\524D\4E1A\52A1\57DF\5B58\5728\591A\4E2A\6709\6548\5E94\7528\6620\5C04\FF0C\8BF7\5148\4FEE\590D\6570\636E\540E\518D\7EF4\62A4\3002'');'),
'        end if;',
'    else',
'        :P64_APP_ID := null;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>48390317208825313
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48390779008825313)
,p_process_sequence=>15
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('\4FDD\5B58\4E1A\52A1\57DF\5E94\7528\6620\5C04')
,p_static_id=>'p64-save-app-bindings'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_domain_id       number := to_number(:P64_DOMAIN_ID);',
'    l_app_id          varchar2(255) := lower(trim(:P64_APP_ID));',
'    l_existing_app_id varchar2(255);',
'    l_existing_count  pls_integer;',
'    l_valid_count     pls_integer;',
'    l_actor           varchar2(255) := coalesce(v(''APP_USER''), user);',
'begin',
'    if l_domain_id is null then',
unistr('        raise_application_error(-20001, ''\4E1A\52A1\57DF\4FDD\5B58\5931\8D25\FF0C\672A\53D6\5F97\4E1A\52A1\57DF ID\3002'');'),
'    end if;',
'',
'    select min(ad.app_id), count(*)',
'      into l_existing_app_id, l_existing_count',
'      from kbot_app_domain ad',
'     where ad.domain_id = l_domain_id',
'       and ad.status = ''ACTIVE'';',
'',
'    if l_existing_count > 1 then',
unistr('        raise_application_error(-20002, ''\4E00\4E2A\4E1A\52A1\57DF\53EA\80FD\7ED1\5B9A\4E00\4E2A\5E94\7528\FF1B\5F53\524D\6570\636E\5B58\5728\591A\4E2A\6709\6548\6620\5C04\FF0C\5DF2\62D2\7EDD\4FDD\5B58\3002'');'),
'    end if;',
'',
'    if l_existing_app_id in (''aiops'', ''km_asset'') then',
'        if l_app_id is not null and l_app_id <> l_existing_app_id then',
unistr('            raise_application_error(-20003, ''AIOps \4E0E\77E5\8BC6\8D44\4EA7\4E1A\52A1\57DF\7531\670D\52A1\811A\672C\7EF4\62A4\FF0C\4E0D\80FD\5728\6B64\66F4\6362\6216\79FB\9664\3002'');'),
'        end if;',
'        l_app_id := l_existing_app_id;',
'    elsif l_app_id in (''aiops'', ''km_asset'') then',
unistr('        raise_application_error(-20004, ''AIOps \4E0E\77E5\8BC6\8D44\4EA7\4E1A\52A1\57DF\53EA\80FD\7531\670D\52A1\811A\672C\521B\5EFA\3002'');'),
'    end if;',
'',
'    if l_app_id is null then',
unistr('        raise_application_error(-20005, ''\8BF7\9009\62E9\4E00\4E2A\9002\7528\5E94\7528\3002'');'),
'    end if;',
'',
'    select count(*)',
'      into l_valid_count',
'      from kbot_platform_app a',
'     where a.app_id = l_app_id',
'       and a.status = ''ACTIVE''',
'       and a.member_assignable = ''Y'';',
'',
'    if l_valid_count <> 1 then',
unistr('        raise_application_error(-20006, ''\6240\9009\5E94\7528\4E0D\53EF\7528\FF0C\8BF7\5237\65B0\9875\9762\540E\91CD\8BD5\3002'');'),
'    end if;',
'',
'    merge into kbot_app_domain target',
'    using (',
'        select l_app_id as app_id, l_domain_id as domain_id',
'          from dual',
'    ) selected',
'       on (target.app_id = selected.app_id and target.domain_id = selected.domain_id)',
'     when matched then',
'          update set target.status = ''ACTIVE''',
'     when not matched then',
'          insert (app_id, domain_id, status, created_by, created_at)',
'          values (selected.app_id, selected.domain_id, ''ACTIVE'', l_actor, systimestamp);',
'',
'    update kbot_app_domain target',
'       set target.status = ''DISABLED''',
'     where target.domain_id = l_domain_id',
'       and target.app_id <> l_app_id',
'       and target.status = ''ACTIVE'';',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,APPLY-CHANGES'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>unistr('\4E1A\52A1\57DF\53CA\9002\7528\5E94\7528\5DF2\4FDD\5B58\3002')
,p_internal_uid=>48390779008825313
);
