wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48391732321825314)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P86_LOAD_ACCESS_DATA'
,p_static_id=>'p86-load-access-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_app_id         varchar2(64) := lower(trim(apex_application.g_x01));',
'    v_search         varchar2(256) := trim(apex_application.g_x02);',
'    v_catalog_app_id varchar2(64);',
'    v_total          number;',
'    v_can_users      number := 0;',
'    v_can_app_grants number := 0;',
'    v_can_roles      number := 0;',
'    v_is_platform_admin number := 0;',
'    v_actor_security_level number := 0;',
'    v_app_available number := 0;',
'begin',
'    if v_app_id not in (''platform'', ''knowledge_retrieval'', ''aiops'', ''km_asset'', ''unassigned'') then',
unistr('        raise_application_error(-20002, ''\4E0D\652F\6301\7684\4E1A\52A1\5E94\7528\3002'');'),
'    end if;',
'',
'    if v_app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'') then',
'        select count(*)',
'          into v_app_available',
'          from apex_applications a',
'          join apex_application_settings s',
'            on s.application_id = a.application_id',
'           and s.static_id = ''KBOT_LOGICAL_APP_ID''',
'         where a.workspace_id = :WORKSPACE_ID',
'           and a.application_group = ''KBOT Agent Apps''',
'           and nvl(a.availability_status, ''Available'') like ''Available%''',
'           and lower(trim(s.value)) = v_app_id;',
'        if v_app_available = 0 then',
unistr('            raise_application_error(-20003, ''\5F53\524D\4E1A\52A1\5E94\7528\672A\5B89\88C5\6216\4E0D\53EF\7528\FF0C\4E0D\80FD\67E5\770B\6216\7EF4\62A4\5176\6388\6743\3002'');'),
'        end if;',
'    end if;',
'',
'    v_catalog_app_id := case when v_app_id = ''unassigned'' then ''platform'' else v_app_id end;',
'',
'    select nvl(max(max_security_level), 0)',
'      into v_actor_security_level',
'      from kbot_platform_user',
'     where upper(user_id) = upper(:APP_USER)',
'       and status = ''ACTIVE'';',
'',
'    select count(*)',
'      into v_total',
'      from kbot_platform_user u',
'     where (v_search is null',
'        or upper(u.user_id) like ''%'' || upper(v_search) || ''%''',
'        or upper(nvl(u.display_name, '''')) like ''%'' || upper(v_search) || ''%'')',
'       and ((v_app_id = ''unassigned''',
'             and u.account_origin = ''PLATFORM''',
'             and u.is_protected = ''N''',
'             and not exists (',
'                 select 1 from kbot_platform_user_role ur',
'                  where ur.user_id = u.user_id and ur.status = ''ACTIVE''',
'             )',
'             and not exists (',
'                 select 1 from kbot_app_member am',
'                  where am.user_id = u.user_id and am.status = ''ACTIVE''',
'             ))',
'         or (v_app_id = ''platform''',
'             and u.account_origin = ''PLATFORM''',
'             and (u.is_protected = ''Y'' or exists (',
'                 select 1 from kbot_platform_user_role ur',
'                  where ur.user_id = u.user_id',
'                    and ur.app_id = ''platform''',
'                    and ur.status = ''ACTIVE''',
'             )))',
'         or (v_app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'             and exists (',
'                 select 1 from kbot_app_member am',
'                  where am.app_id = v_app_id',
'                    and am.user_id = u.user_id',
'                    and am.status = ''ACTIVE''',
'             )',
'             and not kbot_apex_auth.is_platform_admin(u.user_id)));',
'',
'    if kbot_apex_auth.is_platform_admin(:APP_USER) then',
'        v_can_users := 1;',
'        v_can_app_grants := 1;',
'        v_can_roles := 1;',
'        v_is_platform_admin := 1;',
'    else',
'        select nvl(max(case when rp.permission_code = ''platform:user_manage'' then 1 else 0 end), 0),',
'               nvl(max(case when rp.permission_code = ''platform:app_grant_manage'' then 1 else 0 end), 0),',
'               nvl(max(case when rp.permission_code = ''platform:role_manage'' then 1 else 0 end), 0)',
'          into v_can_users, v_can_app_grants, v_can_roles',
'          from kbot_platform_user_role mr',
'          join kbot_app_role r',
'            on r.app_id = mr.app_id',
'           and r.role_code = mr.role_code',
'           and r.status = ''ACTIVE''',
'          join kbot_app_role_permission rp',
'            on rp.app_id = mr.app_id',
'           and rp.role_code = mr.role_code',
'         where mr.app_id = ''platform''',
'           and mr.user_id = :APP_USER',
'          and mr.status = ''ACTIVE'';',
'',
'        v_is_platform_admin := 0;',
'',
'        if v_app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'') then',
'            select case when exists (',
'                       select 1',
'                         from kbot_app_member_role mr',
'                         join kbot_app_role r',
'                           on r.app_id = mr.app_id',
'                          and r.role_code = mr.role_code',
'                          and r.status = ''ACTIVE''',
'                         join kbot_app_role_permission rp',
'                           on rp.app_id = mr.app_id',
'                          and rp.role_code = mr.role_code',
'                        where mr.app_id = v_app_id',
'                          and mr.user_id = :APP_USER',
'                          and mr.status = ''ACTIVE''',
'                          and rp.permission_code = v_app_id || '':role_manage''',
'                   ) then 1 else 0 end',
'              into v_can_roles',
'              from dual;',
'        elsif v_app_id = ''unassigned'' then',
'            v_can_roles := 0;',
'        end if;',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.write(''app_id'', v_app_id);',
'    apex_json.write(''total'', v_total);',
'    apex_json.write(''can_users'', v_can_users = 1);',
'    apex_json.write(''can_app_grants'', v_can_app_grants = 1);',
'    apex_json.write(''can_roles'', v_can_roles = 1);',
'    apex_json.write(''is_platform_admin'', v_is_platform_admin = 1);',
'    apex_json.write(''actor_max_security_level'', v_actor_security_level);',
'',
'    apex_json.open_array(''available_apps'');',
'    for a in (',
'        select lower(trim(s.value)) app_id,',
'               a.application_name',
'          from apex_applications a',
'          join apex_application_settings s',
'            on s.application_id = a.application_id',
'           and s.static_id = ''KBOT_LOGICAL_APP_ID''',
'         where a.workspace_id = :WORKSPACE_ID',
'           and a.application_group = ''KBOT Agent Apps''',
'           and nvl(a.availability_status, ''Available'') like ''Available%''',
'           and lower(trim(s.value)) in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'         order by a.application_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''app_id'', a.app_id);',
'        apex_json.write(''application_name'', a.application_name);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''domains'');',
'    for d in (',
'        select d.domain_id, d.name',
'          from kbot_platform_domain d',
'        where d.status = ''ACTIVE''',
'           and (',
'               v_catalog_app_id = ''platform''',
'               or exists (',
'                   select 1',
'                     from kbot_app_domain ad',
'                    where ad.app_id = v_catalog_app_id',
'                      and ad.domain_id = d.domain_id',
'                      and ad.status = ''ACTIVE''',
'               )',
'           )',
'           and (',
'               kbot_apex_auth.is_platform_admin(:APP_USER)',
'               or exists (',
'                   select 1',
'                     from kbot_platform_user_role mr',
'                     join kbot_app_role r',
'                       on r.app_id = mr.app_id',
'                      and r.role_code = mr.role_code',
'                      and r.status = ''ACTIVE''',
'                     join kbot_app_role_permission rp',
'                       on rp.app_id = mr.app_id',
'                      and rp.role_code = mr.role_code',
'                    where mr.app_id = ''platform''',
'                      and mr.user_id = :APP_USER',
'                      and mr.status = ''ACTIVE''',
'                      and rp.permission_code in (''platform:user_manage'', ''platform:role_manage'', ''platform:app_grant_manage'')',
'               )',
'           )',
'         order by d.created_at desc, d.domain_id desc',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''domain_id'', d.domain_id);',
'        apex_json.write(''name'', d.name);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''permissions'');',
'    for p in (',
'        select permission_code, app_id, display_name',
'          from kbot_permission',
'         where app_id = v_catalog_app_id',
'           and (',
'               kbot_apex_auth.is_platform_admin(:APP_USER)',
'               or v_catalog_app_id <> ''platform''',
'               or exists (',
'                   select 1',
'                     from kbot_platform_user_role actor_ur',
'                     join kbot_platform_user actor_u',
'                       on actor_u.user_id = actor_ur.user_id',
'                      and actor_u.status = ''ACTIVE''',
'                     join kbot_app_role actor_r',
'                       on actor_r.app_id = actor_ur.app_id',
'                      and actor_r.role_code = actor_ur.role_code',
'                      and actor_r.status = ''ACTIVE''',
'                     join kbot_app_role_permission actor_rp',
'                       on actor_rp.app_id = actor_ur.app_id',
'                      and actor_rp.role_code = actor_ur.role_code',
'                    where actor_ur.app_id = ''platform''',
'                      and actor_ur.user_id = :APP_USER',
'                      and actor_ur.status = ''ACTIVE''',
'                      and actor_rp.permission_code = kbot_permission.permission_code',
'               )',
'           )',
'         order by upper(display_name), permission_code',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''permission_code'', p.permission_code);',
'        apex_json.write(''app_id'', p.app_id);',
'        apex_json.write(''display_name'', p.display_name);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''roles'');',
'    for r in (',
'        select r.app_id, r.role_code, r.display_name, r.status, r.is_system,',
'               case when kbot_apex_auth.is_platform_admin(:APP_USER) or r.app_id <> ''platform'' or not exists (',
'                   select 1',
'                     from kbot_app_role_permission target_rp',
'                    where target_rp.app_id = r.app_id',
'                      and target_rp.role_code = r.role_code',
'                      and not exists (',
'                          select 1',
'                            from kbot_platform_user_role actor_ur',
'                            join kbot_platform_user actor_u',
'                              on actor_u.user_id = actor_ur.user_id',
'                             and actor_u.status = ''ACTIVE''',
'                            join kbot_app_role actor_r',
'                              on actor_r.app_id = actor_ur.app_id',
'                             and actor_r.role_code = actor_ur.role_code',
'                             and actor_r.status = ''ACTIVE''',
'                            join kbot_app_role_permission actor_rp',
'                              on actor_rp.app_id = actor_ur.app_id',
'                             and actor_rp.role_code = actor_ur.role_code',
'                           where actor_ur.app_id = ''platform''',
'                             and actor_ur.user_id = :APP_USER',
'                             and actor_ur.status = ''ACTIVE''',
'                             and actor_rp.permission_code = target_rp.permission_code',
'                      )',
'               ) then ''Y'' else ''N'' end assignable',
'          from kbot_app_role r',
'         where r.app_id = v_catalog_app_id',
'         order by case when status = ''ACTIVE'' then 0 else 1 end,',
'                  upper(display_name), role_code',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''app_id'', r.app_id);',
'        apex_json.write(''role_code'', r.role_code);',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.write(''status'', r.status);',
'        apex_json.write(''protected'', r.is_system = ''Y'');',
'        apex_json.write(''editable'', r.is_system <> ''Y'' and r.assignable = ''Y'');',
'        apex_json.open_array(''permissions'');',
'        for rp in (',
'            select permission_code',
'              from kbot_app_role_permission',
'             where app_id = r.app_id',
'               and role_code = r.role_code',
'             order by permission_code',
'        ) loop',
'            apex_json.write(rp.permission_code);',
'        end loop;',
'        apex_json.close_array;',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''users'');',
'    for u in (',
'        select u.user_id, u.display_name, u.max_security_level, u.status,',
'               u.account_origin, u.owner_app_id, u.is_protected,',
'               u.created_at, u.updated_at',
'          from kbot_platform_user u',
'         where (v_search is null',
'            or upper(u.user_id) like ''%'' || upper(v_search) || ''%''',
'            or upper(nvl(u.display_name, '''')) like ''%'' || upper(v_search) || ''%'')',
'           and ((v_app_id = ''unassigned''',
'                 and u.account_origin = ''PLATFORM''',
'                 and u.is_protected = ''N''',
'                 and not exists (',
'                     select 1 from kbot_platform_user_role ur',
'                      where ur.user_id = u.user_id and ur.status = ''ACTIVE''',
'                 )',
'                 and not exists (',
'                     select 1 from kbot_app_member am',
'                      where am.user_id = u.user_id and am.status = ''ACTIVE''',
'                 ))',
'             or (v_app_id = ''platform''',
'                 and u.account_origin = ''PLATFORM''',
'                 and (u.is_protected = ''Y'' or exists (',
'                     select 1 from kbot_platform_user_role ur',
'                      where ur.user_id = u.user_id',
'                        and ur.app_id = ''platform''',
'                        and ur.status = ''ACTIVE''',
'                 )))',
'             or (v_app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'                 and exists (',
'                     select 1 from kbot_app_member am',
'                      where am.app_id = v_app_id',
'                        and am.user_id = u.user_id',
'                        and am.status = ''ACTIVE''',
'                 )',
'                 and not kbot_apex_auth.is_platform_admin(u.user_id)))',
'         order by case when u.is_protected = ''Y'' then 0 else 1 end,',
'                  upper(nvl(u.display_name, u.user_id)), upper(u.user_id)',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''user_id'', u.user_id);',
'        apex_json.write(''display_name'', u.display_name);',
'        apex_json.write(''max_security_level'', u.max_security_level);',
'        apex_json.write(''status'', u.status);',
'        apex_json.write(''account_origin'', u.account_origin);',
'        apex_json.write(''owner_app_id'', u.owner_app_id);',
'        apex_json.write(''protected'', u.is_protected = ''Y'');',
'        apex_json.write(''created_at'', u.created_at);',
'        apex_json.write(''updated_at'', u.updated_at);',
'        apex_json.open_array(''memberships'');',
'        for m in (',
'            select app_id, domain_id, role_code, status, created_by, created_at',
'              from (',
'                    select ur.app_id,',
'                           cast(null as number) domain_id,',
'                           ur.role_code,',
'                           ur.status,',
'                           ur.created_by,',
'                           ur.created_at',
'                      from kbot_platform_user_role ur',
'                     where ur.user_id = u.user_id',
'                    union all',
'                    select mr.app_id,',
'                           rs.domain_id,',
'                           mr.role_code,',
'                           mr.status,',
'                           mr.created_by,',
'                           mr.created_at',
'                      from kbot_app_member_role mr',
'                      join kbot_app_member_role_scope rs',
'                        on rs.app_id = mr.app_id',
'                       and rs.user_id = mr.user_id',
'                       and rs.role_code = mr.role_code',
'                     where mr.user_id = u.user_id',
'                       and mr.scope_mode = ''SELECTED_DOMAINS''',
'                    union all',
'                    select mr.app_id,',
'                           ad.domain_id,',
'                           mr.role_code,',
'                           mr.status,',
'                           mr.created_by,',
'                           mr.created_at',
'                      from kbot_app_member_role mr',
'                      join kbot_app_domain ad',
'                        on ad.app_id = mr.app_id',
'                       and ad.status = ''ACTIVE''',
'                     where mr.user_id = u.user_id',
'                       and mr.scope_mode = ''ALL_APP_DOMAINS''',
'                   )',
'             order by app_id, domain_id, role_code',
'        ) loop',
'            apex_json.open_object;',
'            apex_json.write(''app_id'', m.app_id);',
'            apex_json.write(''domain_id'', m.domain_id);',
'            apex_json.write(''role_code'', m.role_code);',
'            apex_json.write(''status'', m.status);',
'            apex_json.write(''created_by'', m.created_by);',
'            apex_json.write(''created_at'', m.created_at);',
'            apex_json.close_object;',
'        end loop;',
'        apex_json.close_array;',
'        apex_json.open_array(''agents'');',
'        for a in (',
'            select lower(rawtohex(a.agent_id)) agent_id,',
'                   a.display_name,',
'                   d.name domain_name',
'              from kbot_ops_agent a',
'              join kbot_platform_domain d',
'                on d.domain_id = a.domain_id',
'               and d.status = ''ACTIVE''',
'             where v_app_id = ''aiops''',
'               and a.status = ''ACTIVE''',
'               and exists (',
'                   select 1',
'                     from kbot_app_domain ad',
'                    where ad.app_id = ''aiops''',
'                      and ad.domain_id = a.domain_id',
'                      and ad.status = ''ACTIVE''',
'               )',
'               and exists (',
'                   select 1',
'                     from kbot_app_member_role mr',
'                     join kbot_app_role r',
'                       on r.app_id = mr.app_id',
'                      and r.role_code = mr.role_code',
'                      and r.status = ''ACTIVE''',
'                    where mr.app_id = ''aiops''',
'                      and mr.user_id = u.user_id',
'                      and mr.status = ''ACTIVE''',
'                      and exists (',
'                          select 1 from kbot_app_member m',
'                           where m.app_id = mr.app_id',
'                             and m.user_id = mr.user_id',
'                             and m.status = ''ACTIVE''',
'                      )',
'                      and (',
'                          mr.scope_mode = ''ALL_APP_DOMAINS''',
'                          or exists (',
'                              select 1 from kbot_app_member_role_scope rs',
'                               where rs.app_id = mr.app_id',
'                                 and rs.user_id = mr.user_id',
'                                 and rs.role_code = mr.role_code',
'                                 and rs.domain_id = a.domain_id',
'                          )',
'                      )',
'               )',
'             order by upper(d.name), upper(a.display_name), a.agent_id',
'        ) loop',
'            apex_json.open_object;',
'            apex_json.write(''agent_id'', a.agent_id);',
'            apex_json.write(''display_name'', a.display_name);',
'            apex_json.write(''domain_name'', a.domain_name);',
'            apex_json.close_object;',
'        end loop;',
'        apex_json.close_array;',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48350529339823003)
,p_internal_uid=>48391732321825314
);
end;
