wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48392297714825315)
,p_process_sequence=>5
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P87_LOAD_OPTIONS'
,p_static_id=>'p87-load-options'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_user_id varchar2(256) := trim(apex_application.g_x01);',
'    v_can_user_manage number := 0;',
'    v_can_app_grant_manage number := 0;',
'    v_actor_security_level number := 0;',
'    v_user_security_level number := 1;',
'begin',
'    if kbot_apex_auth.is_platform_admin(:APP_USER) then',
'        v_can_user_manage := 1;',
'        v_can_app_grant_manage := 1;',
'    else',
'        select nvl(max(case when rp.permission_code = ''platform:user_manage'' then 1 else 0 end), 0),',
'               nvl(max(case when rp.permission_code = ''platform:app_grant_manage'' then 1 else 0 end), 0)',
'          into v_can_user_manage, v_can_app_grant_manage',
'          from kbot_platform_user_role ur',
'          join kbot_platform_user actor_u',
'            on actor_u.user_id = ur.user_id',
'           and actor_u.status = ''ACTIVE''',
'          join kbot_app_role actor_r',
'            on actor_r.app_id = ur.app_id',
'           and actor_r.role_code = ur.role_code',
'           and actor_r.status = ''ACTIVE''',
'          join kbot_app_role_permission rp',
'            on rp.app_id = ur.app_id',
'           and rp.role_code = ur.role_code',
'         where ur.app_id = ''platform''',
'           and ur.user_id = :APP_USER',
'           and ur.status = ''ACTIVE'';',
'    end if;',
'    select nvl(max(max_security_level), 0)',
'      into v_actor_security_level',
'      from kbot_platform_user',
'     where user_id = :APP_USER',
'       and status = ''ACTIVE'';',
'',
'    select nvl(max(max_security_level), 1)',
'      into v_user_security_level',
'      from kbot_platform_user',
'     where user_id = v_user_id;',
'',
'    apex_json.open_object;',
'    apex_json.write(''can_user_manage'', v_can_user_manage = 1);',
'    apex_json.write(''can_app_grant_manage'', v_can_app_grant_manage = 1);',
'    apex_json.write(''actor_max_security_level'', v_actor_security_level);',
'    apex_json.write(''user_max_security_level'', v_user_security_level);',
'    apex_json.open_array(''available_apps'');',
'    for a in (',
'        select lower(trim(s.value)) app_id,',
'               a.application_name',
'          from apex_applications a',
'          join apex_application_settings s',
'            on s.application_id = a.application_id',
'           and s.static_id = ''KBOT_LOGICAL_APP_ID''',
'         where a.workspace_id = :WORKSPACE_ID',
'           and a.application_group = ''KBOT Agent Apps''',
'           and nvl(a.availability_status, ''Available'') like ''Available%''',
'           and lower(trim(s.value)) in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'         order by a.application_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''app_id'', a.app_id);',
'        apex_json.write(''application_name'', a.application_name);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.open_array(''domains'');',
'    for d in (',
'        select ad.app_id, d.domain_id, d.name, d.description',
'          from kbot_app_domain ad',
'          join kbot_platform_domain d',
'            on d.domain_id = ad.domain_id',
'           and d.status = ''ACTIVE''',
'         where ad.app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'           and ad.status = ''ACTIVE''',
'           and exists (',
'               select 1',
'                 from apex_applications aa',
'                 join apex_application_settings aset',
'                   on aset.application_id = aa.application_id',
'                  and aset.static_id = ''KBOT_LOGICAL_APP_ID''',
'                where aa.workspace_id = :WORKSPACE_ID',
'                  and aa.application_group = ''KBOT Agent Apps''',
'                  and nvl(aa.availability_status, ''Available'') like ''Available%''',
'                  and lower(trim(aset.value)) = ad.app_id',
'           )',
'           and (',
'               kbot_apex_auth.is_platform_admin(:APP_USER)',
'               or exists (',
'                   select 1',
'                     from kbot_platform_user_role mr',
'                     join kbot_app_role r',
'                       on r.app_id = mr.app_id',
'                      and r.role_code = mr.role_code',
'                      and r.status = ''ACTIVE''',
'                     join kbot_app_role_permission rp',
'                       on rp.app_id = mr.app_id',
'                      and rp.role_code = mr.role_code',
'                    where mr.app_id = ''platform''',
'                      and mr.user_id = :APP_USER',
'                      and mr.status = ''ACTIVE''',
'                      and rp.permission_code = ''platform:app_grant_manage''',
'               )',
'           )',
'         order by ad.app_id, upper(d.name), d.domain_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''app_id'', d.app_id);',
'        apex_json.write(''domain_id'', d.domain_id);',
'        apex_json.write(''name'', d.name);',
'        apex_json.write(''description'', d.description);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''roles'');',
'    for r in (',
'        select r.app_id, r.role_code, r.display_name, r.status, r.scope_policy',
'          from kbot_app_role r',
'         where r.app_id in (''platform'', ''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'           and r.status = ''ACTIVE''',
'           and r.role_code not in (''manager'', ''system_admin'')',
'           and (',
'               r.app_id = ''platform''',
'               or exists (',
'                   select 1',
'                     from apex_applications aa',
'                     join apex_application_settings aset',
'                       on aset.application_id = aa.application_id',
'                      and aset.static_id = ''KBOT_LOGICAL_APP_ID''',
'                    where aa.workspace_id = :WORKSPACE_ID',
'                      and aa.application_group = ''KBOT Agent Apps''',
'                      and nvl(aa.availability_status, ''Available'') like ''Available%''',
'                      and lower(trim(aset.value)) = r.app_id',
'               )',
'           )',
'           and (',
'               r.app_id <> ''platform''',
'               or kbot_apex_auth.is_platform_admin(:APP_USER)',
'               or not exists (',
'                   select 1',
'                     from kbot_app_role_permission target_rp',
'                    where target_rp.app_id = r.app_id',
'                      and target_rp.role_code = r.role_code',
'                      and not exists (',
'                          select 1',
'                            from kbot_platform_user_role actor_ur',
'                            join kbot_platform_user actor_u',
'                              on actor_u.user_id = actor_ur.user_id',
'                             and actor_u.status = ''ACTIVE''',
'                            join kbot_app_role actor_r',
'                              on actor_r.app_id = actor_ur.app_id',
'                             and actor_r.role_code = actor_ur.role_code',
'                             and actor_r.status = ''ACTIVE''',
'                            join kbot_app_role_permission actor_rp',
'                              on actor_rp.app_id = actor_ur.app_id',
'                             and actor_rp.role_code = actor_ur.role_code',
'                           where actor_ur.app_id = ''platform''',
'                             and actor_ur.user_id = :APP_USER',
'                             and actor_ur.status = ''ACTIVE''',
'                             and actor_rp.permission_code = target_rp.permission_code',
'                      )',
'               )',
'           )',
'         order by r.app_id, upper(r.display_name), r.role_code',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''app_id'', r.app_id);',
'        apex_json.write(''role_code'', r.role_code);',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.write(''status'', r.status);',
'        apex_json.write(''scope_policy'', r.scope_policy);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''authorized_apps'');',
'    for a in (',
'        select app_id',
'          from (',
'                select distinct ur.app_id',
'                  from kbot_platform_user_role ur',
'                  join kbot_app_role r',
'                    on r.app_id = ur.app_id',
'                   and r.role_code = ur.role_code',
'                   and r.status = ''ACTIVE''',
'                 where ur.user_id = v_user_id',
'                   and ur.status = ''ACTIVE''',
'                union',
'                select distinct mr.app_id',
'                  from kbot_app_member_role mr',
'                  join kbot_app_role r',
'                    on r.app_id = mr.app_id',
'                   and r.role_code = mr.role_code',
'                   and r.status = ''ACTIVE''',
'                 where mr.user_id = v_user_id',
'                   and mr.status = ''ACTIVE''',
'                   and mr.app_id in (''knowledge_retrieval'', ''aiops'', ''km_asset'')',
'               )',
'         order by app_id',
'    ) loop',
'        apex_json.write(a.app_id);',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48350529339823003)
,p_internal_uid=>48392297714825315
);
