wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48395267479825365)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P98_GET_ROLE_AUTHORIZATION'
,p_static_id=>'p98-get-role-authorization'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_target_app          varchar2(64) := lower(trim(apex_application.g_x01));',
'    l_domain_id           number;',
'    l_app_name            varchar2(256);',
'    l_domain_name         varchar2(256);',
'    l_token               varchar2(4000);',
'    l_expires_at          varchar2(128);',
'    l_base_url            varchar2(4000);',
'    l_platform_token      varchar2(4000);',
'    l_platform_expires_at varchar2(128);',
'    l_platform_seq        number;',
'    l_response            clob;',
'    l_context             kbot_apex_auth.t_context;',
'    l_app_available       number := 0;',
'begin',
'    if l_target_app not in (''platform'', ''knowledge_retrieval'', ''aiops'', ''km_asset'') then',
unistr('        raise_application_error(-20001, ''\89D2\8272\7BA1\7406\5E94\7528\53C2\6570\65E0\6548\3002'');'),
'    end if;',
'    if l_target_app <> ''platform'' then',
'        select count(*)',
'          into l_app_available',
'          from apex_applications a',
'          join apex_application_settings s',
'            on s.application_id = a.application_id',
'           and s.static_id = ''KBOT_LOGICAL_APP_ID''',
'         where a.workspace_id = :WORKSPACE_ID',
'           and a.application_group = ''KBOT Agent Apps''',
'           and nvl(a.availability_status, ''Available'') like ''Available%''',
