unistr('            raise_application_error(-20006, ''\5F53\524D\4E1A\52A1\5E94\7528\672A\5B89\88C5\6216\4E0D\53EF\7528\FF0C\4E0D\80FD\7EF4\62A4\5176\89D2\8272\3002'');'),
'        end if;',
'    end if;',
'',
'    if regexp_like(v(''P0_DOMAIN_ID''), ''^\d+$'') then',
'        l_domain_id := to_number(v(''P0_DOMAIN_ID''));',
'    end if;',
'    kbot_apex_auth.acquire_app_context(',
'        p_target_app => l_target_app,',
'        p_requested_domain_id => l_domain_id,',
'        p_result => l_context,',
