'',
'    select max(',
'               case when protocol is not null and host is not null then',
'                   protocol || ''://'' || host ||',
'                   case when port is not null then '':'' || to_char(port) end',
'               end',
'           )',
'      into l_base_url',
'      from kbot_apex_platform_config',
