'       and type_2 = ''SERVICE''',
'       and status = ''ACTIVE'';',
'    if l_base_url is null then',
'        l_base_url := regexp_replace(rtrim(apex_util.host_url(''HOST''), ''/''), '':(8080|8181)$'', '''');',
'    end if;',
'',
'    if l_target_app <> ''platform''',
'       and upper(v(''P0_AUTH_ENTRY_KIND'')) = ''BUSINESS''',
'       and lower(v(''P0_AUTH_APP_ID'')) = l_target_app',
