'        l_expires_at := v(''P0_AUTH_EXPIRES_AT'');',
'        if l_token is null then',
unistr('            raise_application_error(-20002, ''\5F53\524D\5E94\7528\767B\5F55\5DF2\5931\6548\FF0C\8BF7\91CD\65B0\767B\5F55\3002'');'),
'        end if;',
'        if l_expires_at is null',
'           or substr(l_expires_at, 1, 19) <=',
