'        apex_collection.update_member_attribute(''KBOT_ENTRY_TOKENS'', l_platform_seq, 10, l_platform_expires_at);',
'    end if;',
'',
'    if l_target_app = ''platform'' then',
'        l_token := l_platform_token;',
'        l_expires_at := l_platform_expires_at;',
'    else',
'        begin',
'            if regexp_like(v(''P0_DOMAIN_ID''), ''^\d+$'') then',
'                select to_number(c003), c002, c004',
'                  into l_domain_id, l_app_name, l_domain_name',
'                  from apex_collections',
'                 where collection_name = ''KBOT_SSO_ENTRIES''',
'                   and c001 = l_target_app',
'                   and c003 = v(''P0_DOMAIN_ID'')',
'                   and rownum = 1;',
'            else',
'                raise no_data_found;',
'            end if;',
'        exception',
'            when no_data_found then',
'                select to_number(c003), c002, c004',
'                  into l_domain_id, l_app_name, l_domain_name',
'                  from (',
'                        select c002, c003, c004',
'                          from apex_collections',
'                         where collection_name = ''KBOT_SSO_ENTRIES''',
'                           and c001 = l_target_app',
'                         order by to_number(c003)',
'                       )',
'                 where rownum = 1;',
'        end;',
'',
'        begin',
'            select c007, c010',
'              into l_token, l_expires_at',
'              from (',
'                    select c007, c010',
'                      from apex_collections',
'                     where collection_name = ''KBOT_ENTRY_TOKENS''',
'                       and c001 = l_target_app || '':'' || to_char(l_domain_id)',
'                       and c010 is not null',
'                       and substr(c010, 1, 19) >',
'                           to_char(sys_extract_utc(systimestamp + interval ''5'' minute), ''YYYY-MM-DD"T"HH24:MI:SS'')',
'                     order by seq_id desc',
'                   )',
'             where rownum = 1;',
'        exception',
'            when no_data_found then',
'                apex_web_service.g_request_headers.delete;',
'                apex_web_service.g_request_headers(1).name := ''Authorization'';',
'                apex_web_service.g_request_headers(1).value := ''Bearer '' || l_platform_token;',
'                apex_web_service.g_request_headers(2).name := ''Content-Type'';',
'                apex_web_service.g_request_headers(2).value := ''application/json'';',
'                apex_web_service.g_request_headers(3).name := ''Accept'';',
'                apex_web_service.g_request_headers(3).value := ''application/json'';',
'                apex_web_service.g_request_headers(4).name := ''X-Request-ID'';',
'                apex_web_service.g_request_headers(4).value := lower(rawtohex(sys_guid()));',
'                l_response := apex_web_service.make_rest_request(',
'                    p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/exchange'',',
'                    p_http_method => ''POST'',',
'                    p_body => json_object(''app_id'' value l_target_app, ''domain_id'' value l_domain_id)',
'                );',
'                if apex_web_service.g_status_code <> 200 then',
unistr('                    raise_application_error(-20003, ''\76EE\6807\5E94\7528\89D2\8272\7BA1\7406\4F1A\8BDD\4EA4\6362\5931\8D25\3002'');'),
'                end if;',
'                l_token := json_value(l_response, ''$.access_token'');',
'                l_expires_at := json_value(l_response, ''$.expires_at'');',
'                if l_token is null or l_expires_at is null',
'                   or upper(json_value(l_response, ''$.entry_kind'')) <> ''BUSINESS''',
'                   or lower(json_value(l_response, ''$.app_id'')) <> l_target_app',
'                   or json_value(l_response, ''$.domain_id'' returning number) <> l_domain_id then',
unistr('                    raise_application_error(-20004, ''\76EE\6807\5E94\7528\89D2\8272\7BA1\7406\4F1A\8BDD\8FD4\56DE\65E0\6548\3002'');'),
'                end if;',
'                l_domain_name := coalesce(json_value(l_response, ''$.domain_name''), l_domain_name);',
'                apex_collection.delete_members(',
'                    p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'                    p_attr_number => 1,',
'                    p_attr_value => l_target_app || '':'' || to_char(l_domain_id)',
'                );',
'                apex_collection.add_member(',
'                    p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'                    p_c001 => l_target_app || '':'' || to_char(l_domain_id),',
'                    p_c002 => ''BUSINESS'', p_c003 => l_target_app,',
'                    p_c004 => to_char(l_domain_id), p_c005 => l_app_name,',
'                    p_c006 => l_domain_name, p_c007 => l_token,',
'                    p_c008 => json_value(l_response, ''$.display_name''),',
'                    p_c009 => case when lower(json_value(l_response, ''$.must_change_password'')) = ''true'' then ''Y'' else ''N'' end,',
'                    p_c010 => l_expires_at',
'                );',
'        end;',
'    end if;',
'',
'    apex_json.open_object;',
