'    apex_json.write(''expires_at'', l_expires_at);',
'    apex_json.write(''app_id'', l_target_app);',
'    if l_domain_id is not null then',
'        apex_json.write(''domain_id'', l_domain_id);',
'    end if;',
'    apex_json.close_object;',
'exception',
'    when no_data_found then',
unistr('        raise_application_error(-20005, ''\5F53\524D\8D26\53F7\6CA1\6709\76EE\6807\5E94\7528\7684\663E\5F0F\6388\6743\3002'');'),
'end;'))
,p_process_clob_language=>'PLSQL'
