wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48395169487825365)
,p_process_sequence=>5
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P98_LOAD_ROLE_IMPACTS'
,p_static_id=>'p98-load-role-impacts'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_app_id varchar2(64) := lower(trim(apex_application.g_x01));',
'    v_app_available number := 0;',
'begin',
'    if v_app_id not in (''platform'', ''knowledge_retrieval'', ''aiops'', ''km_asset'') then',
unistr('        raise_application_error(-20001, ''\5E94\7528\53C2\6570\65E0\6548\3002'');'),
'    end if;',
'    if v_app_id <> ''platform'' then',
'        select count(*)',
'          into v_app_available',
'          from apex_applications a',
'          join apex_application_settings s',
'            on s.application_id = a.application_id',
'           and s.static_id = ''KBOT_LOGICAL_APP_ID''',
'         where a.workspace_id = :WORKSPACE_ID',
'           and a.application_group = ''KBOT Agent Apps''',
'           and nvl(a.availability_status, ''Available'') like ''Available%''',
'           and lower(trim(s.value)) = v_app_id;',
'        if v_app_available = 0 then',
unistr('            raise_application_error(-20002, ''\5F53\524D\4E1A\52A1\5E94\7528\672A\5B89\88C5\6216\4E0D\53EF\7528\FF0C\4E0D\80FD\7EF4\62A4\5176\89D2\8272\3002'');'),
'        end if;',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.open_array(''roles'');',
'    for r in (',
'        select role_code,',
'               count(distinct user_id) user_count,',
'               count(*) membership_count,',
'               count(distinct domain_id) domain_count',
'          from (',
'                select ur.role_code,',
'                       ur.user_id,',
'                       cast(null as number) domain_id',
'                  from kbot_platform_user_role ur',
'                  join kbot_platform_user u',
'                    on u.user_id = ur.user_id',
'                   and u.status = ''ACTIVE''',
'                 where v_app_id = ''platform''',
'                   and ur.app_id = ''platform''',
'                   and ur.status = ''ACTIVE''',
'                union all',
'                select mr.role_code,',
'                       mr.user_id,',
'                       case when mr.scope_mode = ''ALL_APP_DOMAINS'' then ad.domain_id else rs.domain_id end',
'                  from kbot_app_member m',
'                  join kbot_app_member_role mr',
'                    on mr.app_id = m.app_id',
'                   and mr.user_id = m.user_id',
'                  join kbot_platform_user u',
'                    on u.user_id = mr.user_id',
'                   and u.status = ''ACTIVE''',
'                  left join kbot_app_domain ad',
'                    on ad.app_id = mr.app_id',
'                   and ad.status = ''ACTIVE''',
'                   and mr.scope_mode = ''ALL_APP_DOMAINS''',
'                  left join kbot_app_member_role_scope rs',
'                    on rs.app_id = mr.app_id',
'                   and rs.user_id = mr.user_id',
'                   and rs.role_code = mr.role_code',
'                 where v_app_id <> ''platform''',
'                   and mr.app_id = v_app_id',
'                   and m.status = ''ACTIVE''',
'                   and mr.status = ''ACTIVE''',
'               )',
'         group by role_code',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''role_code'', r.role_code);',
'        apex_json.write(''user_count'', r.user_count);',
'        apex_json.write(''membership_count'', r.membership_count);',
'        apex_json.write(''domain_count'', r.domain_count);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48355066473823044)
,p_internal_uid=>48395169487825365
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48395332906825365)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P98_SAVE_PLATFORM_APP_ROLE'
,p_static_id=>'p98-save-platform-app-role'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_app_id          varchar2(64) := lower(trim(apex_application.g_x01));',
'    l_role_code       varchar2(64) := lower(trim(apex_application.g_x02));',
'    l_existing        boolean := upper(trim(apex_application.g_x03)) = ''Y'';',
'    l_payload         clob := apex_application.g_clob_01;',
'    l_display_name    varchar2(256);',
'    l_status          varchar2(16);',
'    l_is_system       varchar2(1);',
'    l_role_count      pls_integer;',
'    l_permission_count pls_integer;',
'    l_distinct_count  pls_integer;',
'    l_unknown_count   pls_integer;',
'begin',
'    select count(*)',
'      into l_role_count',
'      from dual',
'     where kbot_apex_auth.is_platform_admin(:APP_USER);',
'    if l_role_count = 0 then',
unistr('        raise_application_error(-20001, ''\53EA\6709\5E73\53F0\7BA1\7406\5458\53EF\4EE5\4F7F\7528\5E73\53F0\7EA7\5E94\7528\89D2\8272\4FDD\5B58\901A\9053\3002'');'),
'    end if;',
'    if l_app_id not in (''knowledge_retrieval'', ''aiops'', ''km_asset'') then',
unistr('        raise_application_error(-20002, ''\76EE\6807\5E94\7528\65E0\6548\3002'');'),
'    end if;',
'    select count(*)',
'      into l_role_count',
'      from apex_applications a',
'      join apex_application_settings s',
'        on s.application_id = a.application_id',
'       and s.static_id = ''KBOT_LOGICAL_APP_ID''',
'     where a.workspace_id = :WORKSPACE_ID',
'       and a.application_group = ''KBOT Agent Apps''',
'       and nvl(a.availability_status, ''Available'') like ''Available%''',
'       and lower(trim(s.value)) = l_app_id;',
'    if l_role_count = 0 then',
unistr('        raise_application_error(-20015, ''\5F53\524D\4E1A\52A1\5E94\7528\672A\5B89\88C5\6216\4E0D\53EF\7528\FF0C\4E0D\80FD\4FDD\5B58\5176\89D2\8272\3002'');'),
'    end if;',
'    if not regexp_like(l_role_code, ''^[a-z][a-z0-9_]{0,63}$'') then',
unistr('        raise_application_error(-20003, ''\89D2\8272\4EE3\7801\683C\5F0F\65E0\6548\3002'');'),
'    end if;',
'    if l_payload is null or not json_exists(l_payload, ''$'') then',
unistr('        raise_application_error(-20004, ''\89D2\8272\914D\7F6E\6570\636E\65E0\6548\3002'');'),
'    end if;',
'',
'    l_display_name := trim(json_value(l_payload, ''$.display_name''));',
'    l_status := upper(nvl(json_value(l_payload, ''$.status''), ''ACTIVE''));',
'    if l_display_name is null or length(l_display_name) > 256 then',
unistr('        raise_application_error(-20005, ''\89D2\8272\663E\793A\540D\79F0\4E0D\80FD\4E3A\7A7A\4E14\4E0D\80FD\8D85\8FC7 256 \4E2A\5B57\7B26\3002'');'),
'    end if;',
'    if l_status not in (''ACTIVE'', ''DISABLED'') then',
unistr('        raise_application_error(-20006, ''\89D2\8272\72B6\6001\65E0\6548\3002'');'),
'    end if;',
'    select count(*)',
'      into l_role_count',
'      from kbot_platform_app',
'     where app_id = l_app_id',
'       and status = ''ACTIVE'';',
'    if l_role_count = 0 then',
unistr('        raise_application_error(-20007, ''\76EE\6807\5E94\7528\4E0D\5B58\5728\6216\5DF2\505C\7528\3002'');'),
'    end if;',
'',
'    select count(*), count(distinct permission_code)',
'      into l_permission_count, l_distinct_count',
'      from json_table(',
'               l_payload,',
'               ''$.permissions[*]''',
'               columns(permission_code varchar2(256) path ''$'')',
'           );',
'    if l_permission_count > 200 then',
unistr('        raise_application_error(-20008, ''\89D2\8272\6743\9650\6570\91CF\4E0D\80FD\8D85\8FC7 200 \9879\3002'');'),
'    end if;',
'    if l_permission_count <> l_distinct_count then',
unistr('        raise_application_error(-20009, ''\89D2\8272\6743\9650\4E0D\80FD\91CD\590D\3002'');'),
'    end if;',
'    select count(*)',
'      into l_unknown_count',
'      from json_table(',
'               l_payload,',
'               ''$.permissions[*]''',
'               columns(permission_code varchar2(256) path ''$'')',
'           ) p',
'     where not exists (',
'               select 1',
'                 from kbot_permission kp',
'                where kp.app_id = l_app_id',
'                  and kp.permission_code = p.permission_code',
'           );',
'    if l_unknown_count > 0 then',
unistr('        raise_application_error(-20010, ''\5305\542B\4E0D\5C5E\4E8E\76EE\6807\5E94\7528\7684\6743\9650\3002'');'),
'    end if;',
'',
'    if l_existing then',
'        begin',
'            select is_system',
'              into l_is_system',
'              from kbot_app_role',
'             where app_id = l_app_id',
'               and role_code = l_role_code',
'             for update;',
'        exception',
'            when no_data_found then',
unistr('                raise_application_error(-20011, ''\5E94\7528\89D2\8272\4E0D\5B58\5728\3002'');'),
'        end;',
'        if l_is_system = ''Y'' then',
unistr('            raise_application_error(-20012, ''\7CFB\7EDF\89D2\8272\4E0D\80FD\4FEE\6539\3002'');'),
'        end if;',
'        update kbot_app_role',
'           set display_name = l_display_name,',
'               status = l_status,',
'               row_version = row_version + 1',
'         where app_id = l_app_id',
'           and role_code = l_role_code;',
'    else',
'        if l_role_code in (''platform_admin'', ''app_admin'') then',
unistr('            raise_application_error(-20013, ''\8BE5\89D2\8272\4EE3\7801\7531\7CFB\7EDF\4FDD\7559\3002'');'),
'        end if;',
'        select count(*)',
'          into l_role_count',
'          from kbot_app_role',
'         where app_id = l_app_id',
'           and role_code = l_role_code;',
'        if l_role_count > 0 then',
unistr('            raise_application_error(-20014, ''\5E94\7528\89D2\8272\5DF2\5B58\5728\3002'');'),
'        end if;',
'        insert into kbot_app_role (',
'            app_id, role_code, display_name, status,',
'            is_system, scope_policy, row_version',
'        ) values (',
'            l_app_id, l_role_code, l_display_name, ''ACTIVE'',',
'            ''N'', ''SELECTABLE'', 1',
'        );',
'    end if;',
'',
'    delete from kbot_app_role_permission',
'     where app_id = l_app_id',
'       and role_code = l_role_code;',
'    insert into kbot_app_role_permission (app_id, role_code, permission_code)',
'    select l_app_id, l_role_code, p.permission_code',
'      from json_table(',
'               l_payload,',
'               ''$.permissions[*]''',
'               columns(permission_code varchar2(256) path ''$'')',
'           ) p;',
'',
'    apex_json.open_object;',
'    apex_json.write(''saved'', true);',
'    apex_json.write(''app_id'', l_app_id);',
'    apex_json.write(''role_code'', l_role_code);',
'    apex_json.write(''permission_count'', l_permission_count);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48355066473823044)
,p_internal_uid=>48395332906825365
);
end;
