wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48395688222825365)
,p_process_sequence=>5
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P99_LOAD_EDITOR_DATA'
,p_static_id=>'p99-load-editor-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_user_id varchar2(256) := trim(apex_application.g_x01);',
'    v_app_id  varchar2(64) := lower(trim(apex_application.g_x02));',
'    v_app_available number := 0;',
'begin',
'    if v_user_id is null or v_app_id not in (''platform'', ''knowledge_retrieval'', ''aiops'', ''km_asset'') then',
unistr('        raise_application_error(-20001, ''\7F16\8F91\53C2\6570\65E0\6548\3002'');'),
'    end if;',
'',
'    if v_app_id <> ''platform'' then',
'        select count(*)',
'          into v_app_available',
'          from apex_applications a',
'          join apex_application_settings s',
'            on s.application_id = a.application_id',
'           and s.static_id = ''KBOT_LOGICAL_APP_ID''',
'         where a.workspace_id = :WORKSPACE_ID',
'           and a.application_group = ''KBOT Agent Apps''',
'           and nvl(a.availability_status, ''Available'') like ''Available%''',
'           and lower(trim(s.value)) = v_app_id;',
'        if v_app_available = 0 then',
unistr('            raise_application_error(-20002, ''\5F53\524D\4E1A\52A1\5E94\7528\672A\5B89\88C5\6216\4E0D\53EF\7528\FF0C\4E0D\80FD\7F16\8F91\5176\6388\6743\3002'');'),
'        end if;',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.open_object(''user'');',
'    for u in (',
'        select user_id, display_name, status',
'          from kbot_platform_user',
'         where user_id = v_user_id',
'    ) loop',
'        apex_json.write(''user_id'', u.user_id);',
'        apex_json.write(''display_name'', u.display_name);',
'        apex_json.write(''status'', u.status);',
'    end loop;',
'    apex_json.close_object;',
'',
'    apex_json.open_array(''domains'');',
'    for d in (',
'        select domain_id, name, description',
'          from kbot_platform_domain',
'         where status = ''ACTIVE''',
'           and (',
'               v_app_id = ''platform''',
'               or exists (',
'                   select 1',
'                     from kbot_app_domain ad',
'                    where ad.app_id = v_app_id',
'                      and ad.domain_id = kbot_platform_domain.domain_id',
'                      and ad.status = ''ACTIVE''',
'               )',
'           )',
'           and (',
'               kbot_apex_auth.is_platform_admin(:APP_USER)',
'               or exists (',
'                    select 1',
'                      from kbot_platform_user_role mr',
'                     join kbot_app_role r',
'                       on r.app_id = mr.app_id',
'                      and r.role_code = mr.role_code',
'                      and r.status = ''ACTIVE''',
'                     join kbot_app_role_permission rp',
'                       on rp.app_id = mr.app_id',
'                      and rp.role_code = mr.role_code',
'                    where mr.app_id = ''platform''',
'                      and mr.user_id = :APP_USER',
'                      and mr.status = ''ACTIVE''',
'                      and rp.permission_code = case when v_app_id = ''platform'' then ''platform:user_manage'' else ''platform:app_grant_manage'' end',
'               )',
'           )',
'         order by upper(name), domain_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''domain_id'', d.domain_id);',
'        apex_json.write(''name'', d.name);',
'        apex_json.write(''description'', d.description);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''roles'');',
'    for r in (',
'        select r.role_code, r.display_name, r.status, r.scope_policy',
'          from kbot_app_role r',
'         where r.app_id = v_app_id',
'           and r.role_code not in (''manager'', ''system_admin'')',
'           and (',
'               r.app_id <> ''platform''',
'               or kbot_apex_auth.is_platform_admin(:APP_USER)',
'               or not exists (',
'                   select 1',
'                     from kbot_app_role_permission target_rp',
'                    where target_rp.app_id = r.app_id',
'                      and target_rp.role_code = r.role_code',
'                      and not exists (',
'                          select 1',
'                            from kbot_platform_user_role actor_ur',
'                            join kbot_platform_user actor_u',
'                              on actor_u.user_id = actor_ur.user_id',
'                             and actor_u.status = ''ACTIVE''',
'                            join kbot_app_role actor_r',
'                              on actor_r.app_id = actor_ur.app_id',
'                             and actor_r.role_code = actor_ur.role_code',
'                             and actor_r.status = ''ACTIVE''',
'                            join kbot_app_role_permission actor_rp',
'                              on actor_rp.app_id = actor_ur.app_id',
'                             and actor_rp.role_code = actor_ur.role_code',
'                           where actor_ur.app_id = ''platform''',
'                             and actor_ur.user_id = :APP_USER',
'                             and actor_ur.status = ''ACTIVE''',
'                             and actor_rp.permission_code = target_rp.permission_code',
'                      )',
'               )',
'           )',
'         order by case r.status when ''ACTIVE'' then 0 else 1 end,',
'                  upper(r.display_name), r.role_code',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''role_code'', r.role_code);',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.write(''status'', r.status);',
'        apex_json.write(''scope_policy'', r.scope_policy);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''memberships'');',
'    for m in (',
'        select domain_id, role_code, scope_mode, status, created_by, created_at',
'          from (',
'                select cast(null as number) domain_id,',
'                       ur.role_code,',
'                       cast(null as varchar2(32)) scope_mode,',
'                       ur.status,',
'                       ur.created_by,',
'                       ur.created_at',
'                  from kbot_platform_user_role ur',
'                 where v_app_id = ''platform''',
'                   and ur.app_id = ''platform''',
'                   and ur.user_id = v_user_id',
'                union all',
'                select rs.domain_id,',
'                       mr.role_code,',
'                       mr.scope_mode,',
'                       mr.status,',
'                       mr.created_by,',
'                       mr.created_at',
'                  from kbot_app_member_role mr',
'                  join kbot_app_member_role_scope rs',
'                    on rs.app_id = mr.app_id',
'                   and rs.user_id = mr.user_id',
'                   and rs.role_code = mr.role_code',
'                 where v_app_id <> ''platform''',
'                   and mr.user_id = v_user_id',
'                   and mr.app_id = v_app_id',
'                   and mr.scope_mode = ''SELECTED_DOMAINS''',
'                union all',
'                select ad.domain_id,',
'                       mr.role_code,',
'                       mr.scope_mode,',
'                       mr.status,',
'                       mr.created_by,',
'                       mr.created_at',
'                  from kbot_app_member_role mr',
'                  join kbot_app_domain ad',
'                    on ad.app_id = mr.app_id',
'                   and ad.status = ''ACTIVE''',
'                 where v_app_id <> ''platform''',
'                   and mr.user_id = v_user_id',
'                   and mr.app_id = v_app_id',
'                   and mr.scope_mode = ''ALL_APP_DOMAINS''',
'               )',
'         order by domain_id, role_code',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''domain_id'', m.domain_id);',
'        apex_json.write(''role_code'', m.role_code);',
'        apex_json.write(''scope_mode'', m.scope_mode);',
'        apex_json.write(''status'', m.status);',
'        apex_json.write(''created_by'', m.created_by);',
'        apex_json.write(''created_at'', m.created_at);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48350529339823003)
,p_internal_uid=>48395688222825365
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(53984329548850475)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P99_VALIDATE_TARGET_APP'
,p_static_id=>'p99-validate-target-app'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_app_id varchar2(64) := lower(trim(apex_application.g_x01));',
'    v_count number := 0;',
'begin',
'    if v_app_id = ''platform'' then',
'        apex_json.open_object;',
'        apex_json.write(''valid'', true);',
'        apex_json.close_object;',
'        return;',
'    end if;',
'    if v_app_id not in (''knowledge_retrieval'', ''aiops'', ''km_asset'') then',
unistr('        raise_application_error(-20001, ''\4E1A\52A1\5E94\7528\53C2\6570\65E0\6548\3002'');'),
'    end if;',
'    select count(*)',
'      into v_count',
'      from apex_applications a',
'      join apex_application_settings s',
'        on s.application_id = a.application_id',
'       and s.static_id = ''KBOT_LOGICAL_APP_ID''',
'     where a.workspace_id = :WORKSPACE_ID',
'       and a.application_group = ''KBOT Agent Apps''',
'       and nvl(a.availability_status, ''Available'') like ''Available%''',
'       and lower(trim(s.value)) = v_app_id;',
'    if v_count = 0 then',
unistr('        raise_application_error(-20002, ''\5F53\524D\4E1A\52A1\5E94\7528\672A\5B89\88C5\6216\4E0D\53EF\7528\FF0C\4E0D\80FD\4FEE\6539\5176\6388\6743\3002'');'),
'    end if;',
'    apex_json.open_object;',
'    apex_json.write(''valid'', true);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48350529339823003)
,p_internal_uid=>53984329548850475
);
end;
/
prompt --application/pages/page_09999
begin
wwv_flow_imp_page.create_page(
 p_id=>9999
,p_name=>unistr('\767B\5F55\9875')
,p_alias=>'LOGIN'
,p_step_title=>unistr('\5E73\53F0\7BA1\7406-\767B\5F55')
,p_warn_on_unsaved_changes=>'N'
,p_first_item=>'AUTO_FIRST_ITEM'
,p_autocomplete_on_off=>'OFF'
,p_html_page_header=>'<script src="#APP_FILES#js/kbot-theme-init.js?v=20260815_1"></script>'
,p_javascript_file_urls=>'#APP_FILES#js/kbot-login.js?v=20261009_app_description_1'
